static int c8(int v){return v<0?0:(v>255?255:v);}
static uint16_t c565(int r,int g,int b){return vxpe2d_rgb565((uint8_t)c8(r),(uint8_t)c8(g),(uint8_t)c8(b));}
static void unpack(uint16_t c,int* r,int* g,int* b){*r=((c>>11)&31)*255/31;*g=((c>>5)&63)*255/63;*b=(c&31)*255/31;}
static uint8_t q7i(int n,int d){int q=n*128/d;return (uint8_t)(q<0?0:(q>255?255:q));}
const char* vxpe_artstyle_name(VxpeArtStyleId id){static const char* n[VXPE_ARTSTYLE_COUNT]={"Neutral","Pixel Classic","Pixel Modern","Cozy Farm","Dark Fantasy","Neon Action","Pastel Platformer","Retro Handheld","Cel-Shaded Cartoon","Saturated Adventure","Strategy RPG","Painterly Fantasy","Low-Poly 2.5D","Urban Toon","Dungeon Synth"};return (id<VXPE_ARTSTYLE_COUNT)?n[id]:"Neutral";}
void vxpe_artstyle_init(VxpeArtStyleProfile* p,VxpeArtStyleId id){
 if(!p)return;
 memset(p,0,sizeof(*p));
 p->id=(uint8_t)id;p->saturation_q7=128;p->contrast_q7=128;p->tint565=0xFFFFu;p->fog_color565=c565(128,142,150);p->sprite_fx.outline_color=c565(20,24,31);p->sprite_fx.shadow_color=c565(8,12,18);p->sprite_fx.glow_color=0xFFFFu;p->trail_color565=0xFFFFu;p->light_color565=c565(255,240,190);
 switch(id){
 case VXPE_ARTSTYLE_PIXEL_CLASSIC:p->posterize_levels=8;p->saturation_q7=q7i(92,100);p->contrast_q7=q7i(118,100);p->dither_strength=3;p->postprocess=1;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=220;break;
 case VXPE_ARTSTYLE_PIXEL_MODERN:p->posterize_levels=16;p->saturation_q7=q7i(114,100);p->contrast_q7=q7i(110,100);p->dither_strength=2;p->postprocess=1;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=190;break;
 case VXPE_ARTSTYLE_COZY_FARM:p->posterize_levels=24;p->saturation_q7=q7i(108,100);p->contrast_q7=q7i(98,100);p->postprocess=1;p->tint565=c565(255,226,174);p->tint_alpha=10;p->fog_color565=c565(190,211,175);p->fog_strength=22;p->sprite_fx.shadow_dx=1;p->sprite_fx.shadow_dy=2;p->sprite_fx.shadow_alpha=70;p->sprite_fx.shadow_softness=1;break;
 case VXPE_ARTSTYLE_DARK_FANTASY:p->posterize_levels=18;p->saturation_q7=q7i(82,100);p->contrast_q7=q7i(120,100);p->postprocess=1;p->tint565=c565(70,75,118);p->tint_alpha=25;p->fog_color565=c565(32,42,65);p->fog_strength=90;p->vignette_alpha=36;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=180;p->sprite_fx.shadow_dx=2;p->sprite_fx.shadow_dy=3;p->sprite_fx.shadow_alpha=120;break;
 case VXPE_ARTSTYLE_NEON_ACTION:p->posterize_levels=24;p->saturation_q7=q7i(138,100);p->contrast_q7=q7i(118,100);p->postprocess=1;p->tint565=c565(70,110,150);p->tint_alpha=12;p->fog_color565=c565(17,45,68);p->fog_strength=40;p->vignette_alpha=22;p->sprite_fx.glow_px=3;p->sprite_fx.glow_alpha=150;p->sprite_fx.glow_color=c565(55,238,255);p->trail_color565=c565(70,230,255);p->trail_alpha=190;p->trail_width=3;p->light_color565=c565(90,245,255);p->light_alpha=155;break;
 case VXPE_ARTSTYLE_PASTEL_PLATFORMER:p->posterize_levels=24;p->saturation_q7=q7i(92,100);p->contrast_q7=q7i(90,100);p->postprocess=1;p->tint565=c565(255,225,235);p->tint_alpha=10;p->fog_color565=c565(188,210,218);p->fog_strength=20;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=90;p->sprite_fx.outline_color=c565(68,62,81);break;
 case VXPE_ARTSTYLE_RETRO_HANDHELD:p->posterize_levels=4;p->saturation_q7=q7i(50,100);p->contrast_q7=q7i(120,100);p->postprocess=1;p->dither_strength=4;p->tint565=c565(128,165,92);p->tint_alpha=70;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=255;break;
 case VXPE_ARTSTYLE_DUNGEON_SYNTH:p->posterize_levels=12;p->saturation_q7=150;p->contrast_q7=155;p->postprocess=1;p->fog_color565=c565(25,12,44);p->fog_strength=65;p->light_color565=c565(255,163,44);p->light_alpha=190;p->vignette_alpha=80;break;
 case VXPE_ARTSTYLE_URBAN_TOON:p->posterize_levels=8;p->saturation_q7=q7i(125,100);p->contrast_q7=q7i(120,100);p->postprocess=1;p->sprite_fx.outline_px=2;p->sprite_fx.outline_alpha=255;p->sprite_fx.outline_color=c565(13,22,32);p->sprite_fx.shadow_dx=2;p->sprite_fx.shadow_dy=3;p->sprite_fx.shadow_alpha=110;p->fog_color565=c565(133,186,214);p->fog_strength=28;p->trail_color565=c565(44,246,233);p->trail_alpha=220;p->trail_width=3;break;
 case VXPE_ARTSTYLE_CEL_SHADED:p->posterize_levels=12;p->saturation_q7=q7i(118,100);p->contrast_q7=q7i(118,100);p->postprocess=1;p->sprite_fx.outline_px=2;p->sprite_fx.outline_alpha=225;p->sprite_fx.shadow_dx=2;p->sprite_fx.shadow_dy=2;p->sprite_fx.shadow_alpha=95;break;
 case VXPE_ARTSTYLE_SATURATED_ADVENTURE:p->posterize_levels=28;p->saturation_q7=q7i(134,100);p->contrast_q7=q7i(108,100);p->postprocess=1;p->tint565=c565(182,255,221);p->tint_alpha=7;p->fog_color565=c565(34,126,125);p->fog_strength=46;p->vignette_alpha=8;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=120;p->sprite_fx.shadow_dx=1;p->sprite_fx.shadow_dy=3;p->sprite_fx.shadow_alpha=90;p->sprite_fx.shadow_softness=1;p->trail_color565=c565(202,248,255);p->trail_alpha=210;p->trail_width=4;p->light_color565=c565(255,245,190);p->light_alpha=115;break;
 case VXPE_ARTSTYLE_STRATEGY_RPG:p->posterize_levels=20;p->saturation_q7=q7i(112,100);p->contrast_q7=q7i(116,100);p->postprocess=1;p->tint565=c565(255,226,164);p->tint_alpha=8;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=200;p->sprite_fx.shadow_dx=1;p->sprite_fx.shadow_dy=2;p->sprite_fx.shadow_alpha=100;break;
 case VXPE_ARTSTYLE_PAINTERLY:p->posterize_levels=32;p->saturation_q7=q7i(94,100);p->contrast_q7=q7i(94,100);p->postprocess=1;p->tint565=c565(245,230,214);p->tint_alpha=9;p->fog_color565=c565(167,180,181);p->fog_strength=30;p->vignette_alpha=14;break;
 case VXPE_ARTSTYLE_LOW_POLY_25D:p->posterize_levels=16;p->saturation_q7=q7i(110,100);p->contrast_q7=q7i(110,100);p->postprocess=1;p->fog_color565=c565(104,148,155);p->fog_strength=35;p->sprite_fx.outline_px=1;p->sprite_fx.outline_alpha=110;p->sprite_fx.shadow_dx=2;p->sprite_fx.shadow_dy=3;p->sprite_fx.shadow_alpha=90;break;
 default:break;}}
void vxpe_artstyle_apply_scene25d(const VxpeArtStyleProfile* p,VxpeCamera25D* c,VxpeGrade25D* g){if(!p)return;if(c){c->fog_color565=p->fog_color565;c->fog_strength=p->fog_strength;}if(g){g->tint565=p->tint565;g->tint_alpha=p->tint_alpha;g->vignette_alpha=p->vignette_alpha;g->dither_strength=p->dither_strength;g->fog_horizon_alpha=(uint8_t)(p->fog_strength/3u);}}
void vxpe_artstyle_apply_sprite_fx(const VxpeArtStyleProfile* p,VxpeSpriteFxStyle* s){if(p&&s)*s=p->sprite_fx;}
void vxpe_artstyle_postprocess565(uint16_t* fb,int w,int h,const VxpeArtStyleProfile* p){if(!fb||w<=0||h<=0||!p||!p->postprocess)return;int tr,tg,tb;unpack(p->tint565,&tr,&tg,&tb);int levels=p->posterize_levels,step=levels>1?255/(levels-1):0;for(int y=0;y<h;++y)for(int x=0;x<w;++x){int r,g,b;unpack(fb[y*w+x],&r,&g,&b);int l=(77*r+150*g+29*b)>>8;r=l+((r-l)*p->saturation_q7>>7);g=l+((g-l)*p->saturation_q7>>7);b=l+((b-l)*p->saturation_q7>>7);r=128+((r-128)*p->contrast_q7>>7);g=128+((g-128)*p->contrast_q7>>7);b=128+((b-128)*p->contrast_q7>>7);if(p->dither_strength){int q=((x^y)&1)?p->dither_strength:-(int)p->dither_strength;r+=q;g+=q;b+=q;}r=c8(r);g=c8(g);b=c8(b);if(step){r=((r+step/2)/step)*step;g=((g+step/2)/step)*step;b=((b+step/2)/step)*step;}if(p->tint_alpha){int a=p->tint_alpha;r=(r*(255-a)+tr*a)/255;g=(g*(255-a)+tg*a)/255;b=(b*(255-a)+tb*a)/255;}fb[y*w+x]=c565(r,g,b);}}
